const styledConsoleLog=(t,e)=>console.log(`%c${t}`,e),textStyle1="\n  color: #fff;\n  background: rgba(0, 4, 40, 1);\n  font-size: 18px;\n  padding: 12px;\n  margin: 6px 0 6px 14px;\n",textStyle2="\n  font-size: 14px;\n  padding: 16px;\n  margin: 6px 0 6px 0;\n",linkStyle="\n  font-size: 14px;\n  color: #fff;\n  width: 200px;\n  padding: 8px;\n  margin: 6px 0 6px 14px;\n  border-radius: 4px;\n  background: linear-gradient( 109.6deg, rgba(0, 4, 40, 1) 11.2%, rgba(0, 78, 146, 1) 91.1% );\n",urls={contact:"https://voaneves.com/#contato",linkedin:"https://linkedin.com/in/voaneves",github:"https://github.com/voaneves",source:"https://github.com/voaneves/timeline"},messages=[{text:"Hey there! I'm Victor.",style:textStyle1},{text:"It's a pleasure to have you here!",style:textStyle2},{text:"Have a look at my work ▼",style:textStyle2},{text:`Contato    ${urls.contact}`,style:`${linkStyle} ${textStyle2}`},{text:`Linkedin  ${urls.linkedin}`,style:`${linkStyle} ${textStyle2}`},{text:`Github    ${urls.github}`,style:`${linkStyle} ${textStyle2}`},{text:`O código    ${urls.source}`,style:`${linkStyle} ${textStyle2}`},{text:"Hope to see you again 🙂",style:textStyle2}];messages.forEach(({text:t,style:e})=>styledConsoleLog(t,e));